def _sanitize_value_amount(val: Optional[float], *, min_amount: float = 100_000) -> Optional[float]:
    """Drop amounts below ``min_amount`` as noise; ``min_amount`` itself is a valid value."""
    if val is None:
        return None
    try:
        f = float(val)
    except (TypeError, ValueError):
        return None
    return f if f >= min_amount else None

